<template>
  <div class="equipment-type-container">
    <!-- 查询区域 -->
    <el-row>
      <el-col :span="18">
        <el-form :inline="true" :model="queryForm" class="query-form">
          <el-form-item label="类型名称">
            <el-input
              v-model="queryForm.deviceTypeName"
              placeholder="请输入类型名称"
            ></el-input>
          </el-form-item>
          <el-form-item label="设备分类">
            <el-select
              v-model="queryForm.parentId"
              filterable
              placeholder="请选择一级分类"
              clearable
            >
              <el-option
                v-for="item in categoryList"
                :key="item.id"
                :label="item.label"
                :value="item.id"
              >
              </el-option>
            </el-select>
          </el-form-item>
          <el-form-item label="创建日期">
            <el-date-picker
              v-model="queryForm.beginTime"
              type="date"
              placeholder="开始日期"
              value-format="yyyy-MM-dd"
            ></el-date-picker>
            <span style="margin: 0 5px">至</span>
            <el-date-picker
              v-model="queryForm.endTime"
              type="date"
              placeholder="结束日期"
              value-format="yyyy-MM-dd"
            ></el-date-picker>
          </el-form-item>
          <el-form-item label="类型创建人">
            <el-input
              v-model="queryForm.deviceCreateUser"
              placeholder="请输入类型创建人"
            ></el-input>
          </el-form-item>
        </el-form>
      </el-col>
      <el-col :span="6">
        <el-form inline style="text-align: right">
          <el-form-item>
            <el-button type="primary" @click="handleQuery">查询</el-button>
          </el-form-item>
          <el-form-item>
            <el-button @click="handleReset">重置</el-button>
          </el-form-item>
          <el-form-item>
            <el-button type="success" @click="handleAdd('add')">新增</el-button>
          </el-form-item></el-form
        >
      </el-col>
    </el-row>

    <!-- 表格区域 -->
    <el-table
      :data="tableData"
      border
      style="width: 100%; margin-top: 20px"
      row-key="id"
      :tree-props="{ children: 'children', hasChildren: 'hasChildren' }"
    >
      <el-table-column type="index"></el-table-column>
      <el-table-column prop="deviceTypeName" label="分类名称"></el-table-column>
      <el-table-column
        prop="deviceDescription"
        label="设备分类描述"
      ></el-table-column>
      <el-table-column prop="typeCreateTime" label="创建日期"></el-table-column>
      <el-table-column prop="deviceCreateUser" label="创建人"></el-table-column>
      <el-table-column label="操作">
        <template slot-scope="scope">
          <div style="text-align: center">
            <el-button type="primary" @click="handleEdit(scope.row)"
              >编辑</el-button
            >
            <el-button type="danger" @click="handleDelete(scope.row)"
              >删除</el-button
            >
          </div>
        </template>
      </el-table-column>
    </el-table>

    <!-- 分页区域 -->
    <!-- <el-pagination
      @size-change="handleSizeChange"
      @current-change="handleCurrentChange"
      :current-page="currentPage"
      :page-sizes="[10, 20, 30, 40]"
      :page-size="pageSize"
      layout="total, sizes, prev, pager, next, jumper"
      :total="total"
      style="margin-top: 20px; text-align: center"
    >
    </el-pagination> -->
    <!-- 弹窗区域 -->
    <el-dialog
      :title="operateTitle"
      :visible.sync="dialogFormVisible"
      @close="clearQuery"
      :close-on-click-modal="false"
    >
      <el-form :model="insertForm" :rules="insertFormRules" ref="dialogForm">
        <el-form-item label="类型名称">
          <el-input
            v-model="insertForm.deviceTypeName"
            autocomplete="off"
          ></el-input>
        </el-form-item>
        <el-form-item label="关联分类">
          <el-select
            v-model="insertForm.parentId"
            placeholder="请根据需要选择一级菜单关联"
            clearable
            filterable
          >
            <el-option
              v-for="item in categoryList"
              :key="item.id"
              :label="item.label"
              :value="item.id"
            >
            </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="类型描述">
          <el-input
            v-model="insertForm.deviceDescription"
            autocomplete="off"
          ></el-input>
        </el-form-item>
      </el-form>
      <div slot="footer">
        <el-button @click="clearQuery" type="danger">取 消</el-button>
        <el-button type="primary" @click="submitForm">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import request from "@/utils/request.js";
export default {
  data() {
    return {
      queryForm: {
        deviceTypeName: "",
        parentId: "",
        beginTime: "",
        endTime: "",
        deviceCreateUser: "",
      },
      insertForm: {
        id: "",
        deviceTypeName: "",
        parentId: "",
        deviceDescription: "",
        deviceCreateUser: "测试用户",
      },
      insertFormRules: {
        deviceTypeName: [
          { required: true, message: "请输入活动名称", trigger: "blur" },
          { min: 1, max: 25, message: "长度在1-25个字符", trigger: "blur" },
        ],
      },
      searchParam: {}, //查询参数
      categoryList: [], //一级分类
      tableData: [],
      currentPage: 1,
      pageSize: 10,
      total: 50,
      operateTitle: "", //操作类型标题
      dialogFormVisible: false, //弹窗
      operationType: "", //操作类型
    };
  },
  methods: {
    handleQuery() {
      Object.assign(this.searchParam, this.queryForm);
      this.searchByCondition();
    },
    //条件查询
    searchByCondition() {
      request
        .post("deviceType/searchByCondition", {
          queryParam: this.searchParam,
          pageNum: 1,
          pageSize: 1000,
        })
        .then((res) => {
          if (res && res.code == 200) {
            this.tableData = res.data.data;
          }
        });
      this.getAllParentType();
    },
    handleReset() {
      // 重置查询表单
      this.queryForm = {
        deviceTypeName: "",
        parentId: "",
        beginTime: "",
        endTime: "",
        deviceCreateUser: "",
      };
      this.handleQuery();
    },
    //关闭弹窗并清空校验和参数
    clearQuery() {
      this.insertForm = {
        id: "",
        deviceTypeName: "",
        parentId: "",
        deviceDescription: "",
        deviceCreateUser: "测试用户",
      };
      this.dialogFormVisible = false;
      this.$refs.dialogForm.clearValidate();
    },
    handleAdd() {
      this.operateTitle = " 类型新增";
      this.operationType = "add";
      this.insertForm = {
        id: "",
        deviceTypeName: "",
        parentId: "",
        deviceDescription: "",
        deviceCreateUser: "测试用户",
      };
      this.dialogFormVisible = true;
    },
    handleEdit(row) {
      this.operateTitle = row.deviceTypeName + " 编辑";
      this.insertForm = {
        id: row.id,
        deviceTypeName: row.deviceTypeName,
        parentId: row.parentId ? row.parentId : "",
        deviceDescription: row.deviceDescription,
        deviceCreateUser: "测试用户",
        oldParentId: row.parentId,
        oldDeviceTypeName: row.deviceTypeName,
      };
      this.operationType = "edit";
      this.dialogFormVisible = true;
    },
    submitForm() {
      console.log(this.operationType, this.insertForm);
      if (this.operationType === "add") {
        request.post("deviceType/add", this.insertForm).then((res) => {
          if (res && res.code == 200) {
            this.$message.success("类型新增成功！");
            this.clearQuery();
            this.handleReset();
          } 
        });
      } else {
        request
          .post("deviceType/updateDeviceType", this.insertForm)
          .then((res) => {
            if (res && res.code == 200) {
              this.$message.success("类型修改成功！");
              this.clearQuery();
              this.handleReset();
            }
          });
      }
    },
    handleDelete(row) {
      let deleteTip = ""
      if(row.parentId == null){
        deleteTip = row.deviceTypeName+"及其子类"
      }
      else{
        deleteTip = row.deviceTypeName
      }
      this.$confirm(
        "此操作将删除分类：" +deleteTip + ", 是否继续?",
        "提示",
        {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning",
        }
      )
        .then(() => {
          request
            .post("deviceType/deleteDeviceType", {
              id: row.id,
              parentId: row.parentId,
            })
            .then((res) => {
              if (res && res.code == 200) {
                this.$message.success(row.deviceTypeName + "类型删除成功！");
                this.clearQuery();
                this.handleReset();
              }
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    handleSizeChange(val) {
      // 每页条数改变时的回调
      this.pageSize = val;
      // 实际中可根据新的pageSize请求后端数据
    },
    handleCurrentChange(val) {
      // 当前页码改变时的回调
      this.currentPage = val;
      // 实际中可根据新的currentPage请求后端数据
    },
    getAllParentType() {
      request.get("deviceType/getAllParentType").then((res) => {
        if (res && res.code == 200) {
          this.categoryList = res.data;
        }
      });
    },
  },
  created() {
    this.searchByCondition();
    this.getAllParentType();
  },
};
</script>

<style scoped>
.equipment-type-container {
  padding: 20px;
}
.query-form {
  margin-bottom: 20px;
}
</style>
